/* ============================================================
   1. Reset minimalista
   ============================================================ */

*, *::before, *::after {
    box-sizing: border-box;
}

html, body {
    margin: 0;
    padding: 0;
    min-height: 100vh;
}

body {
    font-family: var(--reversa-font-body);
    font-size: var(--reversa-font-size-base);
