    grid-template-rows: auto 1fr auto;
    grid-template-areas:
        "header   header"
        "main     sidebar"
        "footer   footer";
    gap: 0;
}

img, svg, canvas {
    max-width: 100%;
    display: block;
}

a {
    color: var(--reversa-accent);
    text-decoration: none;
}
a:hover, a:focus {
    text-decoration: underline;
}

button {
    font: inherit;
    color: inherit;
