    transition: background 120ms ease, border-color 120ms ease;
}
button:hover, button:focus {
    background: var(--reversa-surface-hover);
    outline: 2px solid transparent;
}
button:focus-visible {
    outline-color: var(--reversa-accent);
    outline-offset: 2px;
